const DEFAULT_SEPARATORS = [",", "\n"];

function parseInput(numbers: string): { separators: string[]; body: string } {
  const header = numbers.match(/^\/\/(?:\[(.+)\]|(.))\n/);
  if (!header) return { separators: DEFAULT_SEPARATORS, body: numbers };
  const custom = header[1]?.split("][") ?? [header[2]];
  return {
    separators: [...DEFAULT_SEPARATORS, ...custom],
    body: numbers.slice(header[0].length),
  };
}

export function add(numbers: string): number {
  if (numbers === "") return 0;

  const { separators, body } = parseInput(numbers);
  const splitter = new RegExp(separators.map(escapeRegExp).join("|"));
  const values = body.split(splitter).map(Number);
  const negatives = values.filter((n) => n < 0);
  if (negatives.length > 0) {
    throw new Error(`negatives not allowed: ${negatives.join(", ")}`);
  }
  return values.filter((n) => n <= MAX_NUMBER).reduce((sum, n) => sum + n, 0);
}
